net.coobird.thumbnailator.ThumbnailParameter paramDefault = new net.coobird.thumbnailator.builders.ThumbnailParameterBuilder()
        .size(100, 100)
        .build();
float defaultQuality = paramDefault.getOutputQuality();

net.coobird.thumbnailator.ThumbnailParameter paramExplicit = new net.coobird.thumbnailator.builders.ThumbnailParameterBuilder()
        .size(100, 100)
        .quality(0.75f)
        .build();
float explicitQuality = paramExplicit.getOutputQuality();

assert Float.isNaN(defaultQuality) : "Expected NaN for default quality, but got: " + defaultQuality;
assert Math.abs(explicitQuality - 0.75f) < 1e-5 : "Expected 0.75f for explicit quality, but got: " + explicitQuality;

System.out.println("__CHECK__ getOutputQuality " + defaultQuality + ", " + explicitQuality);

